  81	/// A coordinate. This is defined as a tagged union to allow for different
  82	/// coordinate systems to be represented.
  83	///
  84	/// A coordinate is only valid within the context of a stable Size value.
  85	/// If any of the sizes in the Size struct change, the coordinate is no
  86	/// longer valid and must be recalculated. A conversion function is provided
  87	/// to migrate to a new Size (which may result in failure).
  88	///
  89	/// The coordinate systems are:
  90	///
  91	///   * surface: (0, 0) is the top-left of the surface (with padding). Negative
  92	///     values are allowed and are off the surface. Likewise, values greater
  93	///     than the surface size are off the surface. Units are pixels.
  94	///
  95	///   * terminal: (0, 0) is the top-left of the terminal grid. This is the
  96	///     same as the surface but with the padding removed. Negative values and
  97	///     values greater than the grid size are allowed and are off the terminal.
  98	///     Units are pixels.
  99	///
 100	///   * grid: (0, 0) is the top-left of the grid. Units are in cells. Negative
 101	///     values are not allowed but values greater than the grid size are
 102	///     possible and are off the grid.
 103	///
 104	pub const Coordinate = union(enum) {
 105	    surface: Surface,
 106	    terminal: Terminal,
 107	    grid: Grid,
 108	
 109	    pub const Tag = @typeInfo(Coordinate).@"union".tag_type.?;
 110	    pub const Surface = struct { x: f64, y: f64 };
 111	    pub const Terminal = struct { x: f64, y: f64 };
 112	    pub const Grid = struct { x: GridSize.Unit, y: GridSize.Unit };
 113	
 114	    /// Convert a coordinate to a different space within the same Size.
 115	    pub fn convert(self: Coordinate, to: Tag, size: Size) Coordinate {
 116	        // Unlikely fast-path but avoid work.
 117	        if (@as(Tag, self) == to) return self;
 118	
 119	        // To avoid the combinatorial explosion of conversion functions, we
 120	        // convert to the surface system first and then reconvert from there.
 121	        const surface = self.convertToSurface(size);
 122	
 123	        return switch (to) {
 124	            .surface => .{ .surface = surface },
 125	            .terminal => .{ .terminal = .{
 126	                .x = surface.x - @as(f64, @floatFromInt(size.padding.left)),
 127	                .y = surface.y - @as(f64, @floatFromInt(size.padding.top)),
 128	            } },
 129	            .grid => grid: {
 130	                // Get rid of the padding.
 131	                const term = (Coordinate{ .surface = surface }).convert(
 132	                    .terminal,
 133	                    size,
 134	                ).terminal;
 135	
 136	                // We need our grid to clamp
 137	                const grid = size.grid();
 138	
 139	                // Calculate the grid position.
 140	                const cell_width: f64 = @as(f64, @floatFromInt(size.cell.width));
 141	                const cell_height: f64 = @as(f64, @floatFromInt(size.cell.height));
 142	                const clamped_x: f64 = @max(0, term.x);
 143	                const clamped_y: f64 = @max(0, term.y);
 144	                const col: GridSize.Unit = @intFromFloat(clamped_x / cell_width);
 145	                const row: GridSize.Unit = @intFromFloat(clamped_y / cell_height);
 146	                const clamped_col: GridSize.Unit = @min(col, grid.columns - 1);
 147	                const clamped_row: GridSize.Unit = @min(row, grid.rows - 1);
 148	                break :grid .{ .grid = .{ .x = clamped_col, .y = clamped_row } };
 149	            },
 150	        };
 151	    }
 152	
 153	    /// Convert a coordinate to the surface coordinate system.
 154	    fn convertToSurface(self: Coordinate, size: Size) Surface {
 155	        return switch (self) {
 156	            .surface => |v| v,
 157	            .terminal => |v| .{
